// ═══ toArray() — returns Object[] ═══
Object[] objects = Stream.of("RELIANCE", "TCS", "HDFC").toArray();
// Type: Object[] — must cast to use as String[]

// ═══ toArray(generator) — returns typed array ═══
String[] symbols = Stream.of("RELIANCE", "TCS", "HDFC").toArray(String[]::new);
// Type: String[] — properly typed!

// ═══ WHY generator is needed ═══
// Java generics use type erasure — at runtime, Stream<String> is just Stream.
// new T[] is illegal. The generator provides the array constructor:
// String[]::new is equivalent to: size -> new String[size]
// The stream calls generator with the element count → gets a String[] of that size.

// ═══ IntStream.toArray() — returns int[] directly (no generator needed) ═══
int[] quantities = IntStream.of(100, 50, 200).toArray();  // int[] — no erasure issue
