@Test void toArrayReturnsObjectArray() {
    Object[] result = Stream.of("A", "B").toArray();
    assertThat(result).isInstanceOf(Object[].class);
}

@Test void toArrayWithGeneratorReturnsTypedArray() {
    String[] result = Stream.of("A", "B").toArray(String[]::new);
    assertThat(result).isInstanceOf(String[].class);
    assertThat(result).containsExactly("A", "B");
}

@Test void intStreamToArrayNeedsNoGenerator() {
    int[] result = IntStream.of(1, 2, 3).toArray();
    assertThat(result).containsExactly(1, 2, 3);
}

@Test void generatorIsIntFunction() {
    // String[]::new is shorthand for: size -> new String[size]
    java.util.function.IntFunction<String[]> generator = String[]::new;
    String[] array = generator.apply(3);  // creates String[3]
    assertThat(array).hasSize(3);
}
