package com.bank.java8;

import org.junit.jupiter.api.Test;
import java.util.stream.Stream;
import static org.assertj.core.api.Assertions.assertThat;

class ToArrayTest {

    @Test
    void typedArrayVsObjectArray() {
        Object[] objs = Stream.of("SAV2001", "CUR3001").toArray();          // Object[]
        String[] strs = Stream.of("SAV2001", "CUR3001").toArray(String[]::new); // String[]

        assertThat(objs).hasSize(2);
        assertThat(strs).containsExactly("SAV2001", "CUR3001");
        assertThat(strs.getClass().getComponentType()).isEqualTo(String.class);
    }
}
